#!/bin/bash\n\n# smg4OS Quick Setup\n# \"For people in a hurry. I understand.\"\n\nset -e\n\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nWIZARD_DIR=\"$(dirname \"$SCRIPT_DIR\")\"\n\nsource \"$WIZARD_DIR/scripts/colors.sh\"\n\nsmg4_say \"Alright, SPEED RUN MODE ACTIVATED!\"\necho \"\"\n\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho -e \"${BLUE}  QUICK SETUP${NC}\"\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho \"\"\n\nsmg4_say \"Just answering a few quick questions...\"\nsleep 1\n\necho \"\"\nread -p \"System hostname (default: smg4-workstation): \" hostname\nhostname=\"${hostname:-smg4-workstation}\"\n\nread -p \"Username (default: gamer): \" username\nusername=\"${username:-gamer}\"\n\nread -p \"Install development tools? (y/n) \" dev_choice\nif [[ $dev_choice == \"y\" || $dev_choice == \"Y\" ]]; then\n    dev=\"yes\"\nelse\n    dev=\"no\"\nfi\n\nread -p \"Install gaming packages? (y/n) \" gaming_choice\nif [[ $gaming_choice == \"y\" || $gaming_choice == \"Y\" ]]; then\n    gaming=\"yes\"\nelse\n    gaming=\"no\"\nfi\n\necho \"\"\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho -e \"${BLUE}  QUICK SETUP SUMMARY${NC}\"\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho \"\"\necho -e \"${WHITE}Hostname:${NC}           $hostname\"\necho -e \"${WHITE}Username:${NC}           $username\"\necho -e \"${WHITE}Dev Tools:${NC}          $dev\"\necho -e \"${WHITE}Gaming:${NC}             $gaming\"\necho \"\"\n\nsmg4_say \"Applying quick setup...\"\nsleep 1\n\necho \"\"\nsmg4_success \"Hostname configured: $hostname\"\nsmg4_success \"User account: $username\"\n\nif [[ $dev == \"yes\" ]]; then\n    smg4_success \"Development tools enabled\"\nfi\n\nif [[ $gaming == \"yes\" ]]; then\n    smg4_success \"Gaming packages enabled\"\nfi\n\necho \"\"\nsmg4_say \"Quick setup complete! Your system is ready to go!\"\nsmg4_say \"Time to get back to what you were doing!\"\n"